import numpy as np
class Node:
    def __init__(self, name, *deps):
        self.name, self.deps, self.value, self.grad = name, deps, None, None
    def forward(self): pass
    def backward(self): pass
class Input(Node):
    def __init__(self, name, value):
        super().__init__(name); self.value = np.asarray(value, float)
class Add(Node):
    def forward(self): a, b = self.deps; self.value = a.value + b.value
    def backward(self):
        a, b = self.deps; a.grad += self.grad; b.grad += self.grad   # 덧셈: 그대로 나눠 준다
class Mul(Node):
    def forward(self): a, b = self.deps; self.value = a.value * b.value
    def backward(self):
        a, b = self.deps; a.grad += b.value * self.grad; b.grad += a.value * self.grad
class Squared(Node):
    def forward(self): (a,) = self.deps; self.value = a.value ** 2
    def backward(self): (a,) = self.deps; a.grad += 2 * a.value * self.grad
x1, x2 = Input("x1", 2.0), Input("x2", 3.0)
s = Add("sum", x1, x2); y = Squared("y", s)
s.forward(); y.forward()                       # 잎 → 뿌리
for n in (x1, x2, s): n.grad = np.zeros_like(n.value)
y.grad = np.ones_like(y.value)                 # 뿌리의 기울기는 1
y.backward(); s.backward()                     # 뿌리 → 잎
print(y.value, s.grad, x1.grad, x2.grad)       # 25.0 10.0 10.0 10.0

from snip_e import Input, Add, Mul, Squared
import numpy as np
def topo(root):
    order, seen = [], set()
    def visit(n):
        if id(n) in seen: return
        seen.add(id(n))
        for d in n.deps: visit(d)
        order.append(n)                 # 의존하는 노드가 모두 먼저 들어간다
    visit(root); return order
def backprop(root):
    nodes = topo(root)
    for n in nodes: n.forward()
    for n in nodes: n.grad = np.zeros_like(n.value)
    root.grad = np.ones_like(root.value)
    for n in reversed(nodes): n.backward()
    return [n.name for n in nodes]
