x = Input("x", 3.0)
y = Squared("y", Add("s", Mul("xx", x, x), x))
print(backprop(y), y.value, x.grad)    # 144.0, dy/dx = 2·12·(2·3+1) = 168

import numpy as np
x = np.array([1., 2., 4.]); y = np.array([4., 6., 7.])   # 훈련 데이터 3개
def train_loss(w, b):
    return np.mean((w * x + b - y) ** 2)
def grad(w, b):
    r = w * x + b - y                                     # 잔차
    return np.mean(2 * r * x), np.mean(2 * r)             # ∂/∂w, ∂/∂b
print(train_loss(2, 1), train_loss(1, 1))                 # 2.0, 5.667
w, b, lr = 0.0, 1.0, 0.01
for step in range(10):
    L = train_loss(w, b); gw, gb = grad(w, b)
    if step in (0, 1, 9): print(step, round(L, 4), round(gw, 4), round(gb, 4))
    w, b = w - lr * gw, b - lr * gb
print(round(w, 4), round(b, 4), round(train_loss(w, b), 4))
for lr in (0.01, 0.12, 0.13):                            # 학습률 비교(1000걸음)
    w, b = 0.0, 1.0
    for _ in range(1000):
        gw, gb = grad(w, b); w, b = w - lr * gw, b - lr * gb
    print(lr, round(train_loss(w, b), 4))
A = np.c_[x, np.ones(3)]
print(np.linalg.lstsq(A, y, rcond=None)[0], round(train_loss(*np.linalg.lstsq(A, y, rcond=None)[0]),4))
